import os
import pandas as pd

def clean_text(text):
    """ 清洗文本，移除空格和换行符 """
    if isinstance(text, str):
        return text.replace(" ", "").replace("\n", "")
    return text

def extract_specific_columns(folder_path, output_file):
    all_data = []  # 用于存储所有提取的数据

    for filename in os.listdir(folder_path):
        if filename.endswith('.xlsx'):
            file_path = os.path.join(folder_path, filename)

            try:
                # 使用openpyxl引擎读取Excel文件，并将所有数据转换为字符串
                df = pd.read_excel(file_path, engine='openpyxl', dtype=str)

                # 清洗数据
                df = df.applymap(clean_text)

                # 提取需要的列
                if "证券名称" in df.columns and "业绩修正原因说明" in df.columns:
                    all_data.append(df[["证券名称", "业绩修正原因说明"]])
                else:
                    print(f"文件 '{filename}' 中缺少所需列。")

            except Exception as e:
                print(f"处理文件 '{filename}' 时出现错误：{e}")

    # 合并所有提取的数据
    if all_data:
        extracted_data = pd.concat(all_data, ignore_index=True)
        # 将提取的数据保存到新的Excel文件中
        extracted_data.to_excel(output_file, engine='openpyxl', index=False)
        print(f"提取完成，数据已保存到：{output_file}")
    else:
        print("没有提取到任何数据。")

# 文件夹路径
folder_path = '/Users/yangjining/Downloads/cr_sheets'  # 请将这里的路径替换为您的文件夹路径
output_file = '/Users/yangjining/Downloads/cr_sheets/output.xlsx'  # 输出文件路径

# 调用函数
extract_specific_columns(folder_path, output_file)
